import boto3


def get_translate_client(region_name="us-east-1"):
    return boto3.client("translate", region_name=region_name)

def normalize_payload(payload):
    # Basic normalization for text translation
    return {
        "Text": payload["text"],
        "SourceLanguageCode": payload["source_language"],
        "TargetLanguageCode": payload["target_language"],
    }


def parse_translation_response(response, original_payload):
    return {
        "text": response["TranslatedText"],
        "source_language": original_payload["SourceLanguageCode"],
        "target_language": original_payload["TargetLanguageCode"],
    }

def normalize_batch_payload(payloads):
    # For batch translation, payloads will be a list of dictionaries
    # Each dictionary should have 'text', 'source_language', 'target_language'
    return [
        {
            "Text": p["text"],
            "SourceLanguageCode": p["source_language"],
            "TargetLanguageCode": p["target_language"],
        }
        for p in payloads
    ]

def parse_batch_translation_response(responses, original_payloads):
    translated_texts = []
    for i, response in enumerate(responses):
        translated_texts.append(
            {
                "text": response["TranslatedText"],
                "source_language": original_payloads[i]["SourceLanguageCode"],
                "target_language": original_payloads[i]["TargetLanguageCode"],
            }
        )
    return translated_texts

import boto3
from translation_client import get_translate_client
from translation_models import normalize_batch_payload, parse_batch_translation_response


def batch_translate(payloads, config=None):
    config = config or {}
    client = get_translate_client(region_name=config.get("region"))

    normalized_payloads = normalize_batch_payload(payloads)
    translated_responses = []

    for item in normalized_payloads:
        response = client.translate_text(
            Text=item["Text"],
            SourceLanguageCode=item["SourceLanguageCode"],
            TargetLanguageCode=item["TargetLanguageCode"],
        )
        translated_responses.append(response)

    return parse_batch_translation_response(translated_responses, normalized_payloads)

import boto3
from translation_client import get_translate_client
from translation_models import parse_translation_response


def translate_dictionary_values(payload, config=None):
    config = config or {}
    client = get_translate_client(region_name=config.get("region"))

    translated_dict = {}
    source_language = payload["source_language"]
    target_language = payload["target_language"]

    for key, value in payload["data"].items():
        if isinstance(value, str):
            response = client.translate_text(
                Text=value,
                SourceLanguageCode=source_language,
                TargetLanguageCode=target_language,
            )
            translated_dict[key] = response["TranslatedText"]
        else:
            translated_dict[key] = value

    return {
        "data": translated_dict,
        "source_language": source_language,
        "target_language": target_language,
    }
